/* Extend the existing guide and planner without replacing their workflows. */
const additionalRepairCategories = {
 'Roofing': ['⌂','Roof leak','Broken or missing roof tiles','Roof sheet damage','Roof flashing repair'],
 'Gutters & Downpipes': ['☂','Blocked gutter','Leaking gutter','Damaged downpipe','Gutter replacement'],
 'Damp & Waterproofing': ['◈','Rising damp','Water penetration','Shower waterproofing','Balcony waterproofing'],
 'Ceilings & Drywall': ['▤','Sagging ceiling','Ceiling water damage','Drywall damage','Cornice repair'],
 'Carpentry & Cupboards': ['⚒','Cupboard hinge or door','Damaged shelving','Kitchen cupboard repair','Timber repair'],
 'Windows & Glass': ['▣','Cracked or broken glass','Window will not close','Window handle or hinge','Window seal leak'],
 'Gates & Garage Doors': ['▥','Gate motor fault','Garage door fault','Remote or access control','Gate off its track'],
 'Appliances': ['▧','Oven or hob fault','Extractor fan fault','Washing machine connection','Other fitted appliance'],
 'Air Conditioning & Ventilation': ['❄','Air conditioner not cooling','Air conditioner leaking','Ventilation fan fault','Service required'],
 'Gardens & Outdoor Areas': ['♧','Garden maintenance','Tree or branch concern','Irrigation fault','Outdoor area repair'],
 'Pest Control': ['✧','Rodents','Cockroaches or ants','Termites or wood borer','Other pest issue'],
 'Cleaning & Waste Removal': ['♲','Deep cleaning','Rubble removal','Blocked refuse area','Post-work cleaning'],
 'Renovations & Refurbishments': ['▦','Kitchen renovation','Bathroom renovation','Property refurbishment','Interior alterations','Other renovation request']
};
for (const [name,[icon,...issues]] of Object.entries(additionalRepairCategories)) guide[name]={icon,issues,questions:[['Where is the issue?',['Inside','Outside','Communal area']],['How extensive is it?',['Small area','One room / section','Several areas']],['When did you first notice it?',['Today','This week','Earlier']]]};
// A single 24px stroke style keeps repair-category marks consistent across devices.
const repairIconPaths={
 'Plumbing':'<path d="M4 10h16v5h-5v6h-6v-6H4zM12 10V5m-4 0h8M3 10v5m18-5v5"/>',
 'Electrical':'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',
 'Doors & locks':'<path d="M5 22V3h14v19M9 22V7h6v15M12 14h.01M3 22h18"/>',
 'Painting':'<path d="M4 3h14v7H4zM18 6h3v8h-9v3m-2 0h4v5h-4z"/>',
 'Tiling':'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M3 9h18M3 15h18M9 3v18M15 3v18"/>',
 'General maintenance':'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7"/>',
 'Roofing':'<path d="m2 11 10-8 10 8M4 10v10h16V10M7 7V3h3m-4 9 6-5 6 5"/>',
 'Gutters & Downpipes':'<path d="M3 5h15v5H3zM18 7h3v10a4 4 0 0 1-4 4h-2v-4h2V10M6 2v3m5-3v3"/>',
 'Damp & Waterproofing':'<path d="m12 2 8 3v6c0 5-4 9-8 11-4-2-8-6-8-11V5zM12 7s-3 4-3 6a3 3 0 0 0 6 0c0-2-3-6-3-6Z"/>',
 'Ceilings & Drywall':'<path d="M3 4h18v16H3zM3 9h18M8 9v11M16 9v11M10 4v5"/>',
 'Carpentry & Cupboards':'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M12 3v18M9 10v4m6-4v4M4 17h16"/>',
 'Windows & Glass':'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M12 3v18M3 12h18m12-5 2-2m-2 5 3-3"/>',
 'Gates & Garage Doors':'<path d="m2 8 10-5 10 5M4 8v13h16V8M7 21V10h10v11M7 14h10M7 18h10"/>',
 'Appliances':'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M5 7h14M8 4.5h.01M11 4.5h.01"/><circle cx="12" cy="14" r="4"/>',
 'Air Conditioning & Ventilation':'<rect x="2" y="3" width="20" height="8" rx="2"/><path d="M5 8h14M7 14v4m5-4v7m5-7v4"/>',
 'Gardens & Outdoor Areas':'<path d="M12 21v-9M12 15C4 15 3 10 3 5c6 0 9 4 9 10Zm0-3c0-6 3-9 9-9 0 6-3 9-9 9ZM6 21h12"/>',
 'Pest Control':'<path d="m8 5-2-3m10 3 2-3M8 9H3m18 0h-5M8 14H2m20 0h-6M8 18l-4 4m12-4 4 4M12 7v13"/><rect x="8" y="5" width="8" height="15" rx="4"/>',
 'Cleaning & Waste Removal':'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
 'Renovations & Refurbishments':'<path d="m2 10 10-8 10 8M5 10v11h7M9 21v-7h4m3-2 5 5-5 5-3-3 5-5M15 13l2-2"/>'
};
for(const [name,paths] of Object.entries(repairIconPaths))guide[name].icon=`<svg class="repair-line-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths}</svg>`;
renderReport=function(){app.innerHTML=heading('Let’s get it sorted.','Report an issue against a linked property.',false)+(role==='tenant'?tenantSelector():'')+`<div class="reportwrap"><div class="panel"><h2>What needs attention?</h2><label class="category-search-label" for="repairCategorySearch">Search categories or specific repairs</label><input id="repairCategorySearch" type="search" placeholder="Try toilet, no power, roof leak or renovation…" style="width:100%"><p id="categorySearchCount" class="muted" aria-live="polite"></p><div class="categorygrid" id="repairCategoryGrid"></div><div class="notice">For immediate danger, use your property's established emergency contact.</div></div></div>`;const input=$('#repairCategorySearch'),grid=$('#repairCategoryGrid');const update=()=>{const q=input.value.trim().toLowerCase();const list=Object.entries(guide).filter(([c,g])=>(c+' '+g.issues.join(' ')).toLowerCase().includes(q));grid.innerHTML=list.map(([c,g])=>`<button class="category" data-repair-category="${esc(c)}"><span>${g.icon}</span><b>${esc(c)}</b><small>${esc(g.issues.slice(0,3).join(' · '))}</small></button>`).join('')||'<p>No matching repairs. Try another word.</p>';$('#categorySearchCount').textContent=list.length+' of '+Object.keys(guide).length+' categories';grid.querySelectorAll('[data-repair-category]').forEach(b=>b.onclick=()=>reportForm(b.dataset.repairCategory))};input.oninput=update;update();wireTenant()};
const reportWithRepairOptions=reportForm;
reportForm=function(category='Plumbing'){reportWithRepairOptions(category);const issue=modal.querySelector('select[name="issue"]');if(!issue)return;const search=document.createElement('input');search.type='search';search.placeholder='Search repair options…';search.setAttribute('aria-label','Search specific repair options');issue.before(search);const options=[...issue.options].map(o=>o.textContent);search.oninput=()=>{const selected=issue.value;const filtered=options.filter(x=>x.toLowerCase().includes(search.value.toLowerCase()));issue.innerHTML=filtered.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')||'<option value="">No matching repair options</option>';issue.required=true}};

function operationStatus(b){return b.status==='Attended'?(b.visitOutcome==='completed'?'Completed':'Attended'):b.onSiteAt&&b.status==='Accepted'?'On Site':b.status}
function operationMinutes(when){return Number(when.slice(11,13))*60+Number(when.slice(14,16))}
function operationGeometry(b){const start=operationMinutes(b.when),end=start+Number(b.duration||60);return {left:Math.max(0,Math.min(480,start-540))/480*100,width:Math.max(0,Math.min(1020,end)-Math.max(540,start))/480*100,outside:start<540||end>1020}}
function operationTimeRange(b){const start=operationMinutes(b.when),end=start+Number(b.duration||60);return b.when.slice(11,16)+'–'+String(Math.floor(end/60)%24).padStart(2,'0')+':'+String(end%60).padStart(2,'0')}
function operationWeek(){const d=keyDate(privateCalendarDay);d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()+i);return dateKey(x)})}
function operationLanes(bookings){const ends=[];return bookings.sort((a,b)=>a.when.localeCompare(b.when)).map(b=>{const start=operationMinutes(b.when),end=start+Number(b.duration||60);let lane=ends.findIndex(e=>e<=start);if(lane<0)lane=ends.length;ends[lane]=end;return {b,lane}})}
let operationsMode='week';
function operationDays(){if(operationsMode==='day')return [privateCalendarDay];if(operationsMode==='week'||operationsMode==='working')return operationsMode==='working'?operationWeek().slice(0,5):operationWeek();const d=keyDate(privateCalendarDay),year=d.getUTCFullYear(),month=d.getUTCMonth(),count=new Date(Date.UTC(year,month+1,0)).getUTCDate();return Array.from({length:count},(_,i)=>dateKey(new Date(Date.UTC(year,month,i+1))))}
function operationsPeriodLabel(){const days=operationDays();return operationsMode==='month'?keyDate(privateCalendarDay).toLocaleDateString('en-ZA',{month:'long',year:'numeric',timeZone:'UTC'}):days.length===1?days[0]:days[0]+' – '+days.at(-1)}

const previousPrivatePlanner=renderPrivatePlanner;
let operationsSearch='';
function operationsVisibleSubbies(){return state.subbies.filter(s=>(privateSubbieFilter==='all'||s.id===privateSubbieFilter)&&`${s.name} ${s.trade} ${s.contact||''}`.toLowerCase().includes(operationsSearch.trim().toLowerCase()))}
function operationGroups(){let days=operationDays();const compact=typeof window!=='undefined'&&window.innerWidth<760,limit=compact?2:7;if(operationsMode==='month'&&!compact){const offset=(keyDate(days[0]).getUTCDay()+6)%7;days=[...Array(offset).fill(null),...days];while(days.length%7)days.push(null)}const groups=[];for(let i=0;i<days.length;i+=limit)groups.push(days.slice(i,i+limit));return groups}
function operationsBoard(days,subbies,bookings){const active=days.filter(Boolean),today=new Date(Date.now()+7200000).toISOString().slice(0,10);return `<section class="operations-week"><div class="operations-week-label">${active[0]}${active.length>1?' – '+active.at(-1):''}</div><div class="operations-grid" style="--days:${days.length}"><div class="operations-name operations-header">Subcontractor</div>${days.map(day=>day?`<div class="operations-header ${[0,6].includes(keyDate(day).getUTCDay())?'operations-weekend':''} ${day===today?'operations-today':''}"><b>${keyDate(day).toLocaleDateString('en-ZA',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'})}</b><div class="operations-hours"><span>09:00</span><span>13:00</span><span>17:00</span></div></div>`:'<div class="operations-header operations-outside-month" aria-label="Outside selected month"></div>').join('')}${subbies.map(s=>`<div class="operations-name"><b>${esc(s.name)}</b><small>${esc(s.trade)}</small></div>${days.map(day=>{if(!day)return '<div class="operations-day operations-outside-month"></div>';const entries=operationLanes(bookings.filter(b=>b.subbie===s.id&&b.when.startsWith(day))),lanes=Math.max(1,...entries.map(e=>e.lane+1));return `<div class="operations-day ${[0,6].includes(keyDate(day).getUTCDay())?'operations-weekend':''} ${day===today?'operations-today':''}" style="min-height:${lanes*76+8}px">${entries.map(({b,lane})=>{const j=bookingJob(b),g=operationGeometry(b);return g.width>0?`<button class="operations-job ${['Cancelled','Declined'].includes(b.status)?'inactive':''} ${operationStatus(b)==='Completed'?'done':''}" style="left:${g.left}%;width:${g.width}%;top:${lane*76+4}px" onclick="privateBookingDetail('${b.id}')" aria-label="${esc(j?.ref+' · '+operationTimeRange(b)+' · '+property(j?.property)?.name+' · '+operationStatus(b))}" title="${esc(j?.ref+' · '+operationTimeRange(b)+' · '+property(j?.property)?.name+' · '+j?.title+' · '+operationStatus(b))}"><b>${esc(j?.ref)}</b><span>${operationTimeRange(b)}</span><strong>${esc(property(j?.property)?.name)}</strong><small>${operationStatus(b)}${b.overlapAuthorisations?.length?' · overlap authorised':''}${g.outside?' · outside hours':''}</small></button>`:`<button class="operations-outside" style="top:${lane*76+4}px" onclick="privateBookingDetail('${b.id}')">${esc(j?.ref)} · ${operationTimeRange(b)}<br>Outside 09:00–17:00</button>`}).join('')||'<span class="operations-free">Available</span>'}</div>`}).join('')}`).join('')}</div></section>`}
function operationsMonthDayBookings(sid,day){if(role!=='sevlink')return [];return filteredPrivateBookings().filter(b=>b.subbie===sid&&b.when.startsWith(day)).sort((a,b)=>a.when.localeCompare(b.when))}
function operationsMonthCell(s,day){const bookings=operationsMonthDayBookings(s.id,day),count=bookings.length;const cls=bookings.some(b=>operationStatus(b)==='On Site')?'onsite':count&&bookings.every(b=>['Attended','Completed','Cancelled','Declined'].includes(operationStatus(b)))?'finished':'';return `<button class="operations-month-count ${cls}" ${count?'':'disabled'} onclick="operationsDayDetail('${s.id}','${day}')" aria-label="${esc(s.name)} · ${day} · ${count} appointments" title="${esc(s.name)} · ${day} · ${count} appointments">${count||''}</button>`}
function operationsMonthMarkup(subbies){const days=operationDays(),today=new Date(Date.now()+7200000).toISOString().slice(0,10),narrow=typeof window!=='undefined'&&window.innerWidth<760;if(narrow){const offset=(keyDate(days[0]).getUTCDay()+6)%7;return subbies.map(s=>`<section class="operations-mobile-month"><h2>${esc(s.name)}</h2><p>${esc(s.trade)}</p><div class="operations-mobile-month-grid">${['Mo','Tu','We','Th','Fr','Sa','Su'].map(d=>`<b>${d}</b>`).join('')}${Array(offset).fill('<span></span>').join('')}${days.map(day=>`<div class="${[0,6].includes(keyDate(day).getUTCDay())?'operations-weekend':''}"><small>${Number(day.slice(-2))}</small>${operationsMonthCell(s,day)}</div>`).join('')}</div></section>`).join('')}
return `<div class="operations-month-table-wrap" tabindex="0" aria-label="Monthly subcontractor bookings, scroll vertically"><table class="operations-month-table"><colgroup><col class="operations-month-name-col">${days.map(()=>'<col>').join('')}</colgroup><thead><tr><th scope="col" class="operations-month-name">Subcontractor</th>${days.map(day=>`<th scope="col" class="${[0,6].includes(keyDate(day).getUTCDay())?'operations-weekend':''} ${day===today?'operations-today':''}" title="${day}"><span>${keyDate(day).toLocaleDateString('en-ZA',{weekday:'short',timeZone:'UTC'}).slice(0,2)}</span><b>${day.slice(-2)}</b></th>`).join('')}</tr></thead><tbody>${subbies.map(s=>`<tr><th scope="row" class="operations-month-name" title="${esc(s.name)} · ${esc(s.trade)}"><b>${esc(s.name)}</b><small>${esc(s.trade)}</small></th>${days.map(day=>`<td class="${[0,6].includes(keyDate(day).getUTCDay())?'operations-weekend':''} ${day===today?'operations-today':''}">${operationsMonthCell(s,day)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">Numbers show appointments per subcontractor per day. Select a number for the job list, times, properties and status actions.</p>`}
function operationsDayDetail(sid,day){if(role!=='sevlink')return;const s=state.subbies.find(s=>s.id===sid);if(!s)return;const bookings=operationsMonthDayBookings(sid,day);enterDialogRoute({type:'operationsDay',sid,day});modal.innerHTML=`<button class="close" onclick="modal.close()" aria-label="Close">×</button><span class="eyebrow">SEVLINK OPERATIONS ONLY</span><h1>${esc(s.name)}</h1><p>${keyDate(day).toLocaleDateString('en-ZA',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})} · SAST<br>${bookings.length} appointments · ${esc(s.trade)}</p>${bookings.map(b=>{const j=bookingJob(b),p=property(j?.property);return `<div class="operations-day-job"><span class="eyebrow">${esc(j?.ref)} · ${operationTimeRange(b)}</span><h2>${esc(p?.name)}</h2><p>${esc(p?.address)}<br>${esc(j?.title)}</p>${badge(operationStatus(b))}<div class="actions"><button class="primary" onclick="privateBookingDetail('${b.id}')">Open appointment / update status</button></div></div>`}).join('')||'<p>No appointments match the current filter.</p>'}`;if(!modal.open)modal.showModal();decorateDialogBack()}
const operationsShowPreviousRoute=showDialogRoute;
showDialogRoute=function(route){if(route?.type!=='operationsDay')return operationsShowPreviousRoute(route);if(dialogUserScope()!==dialogRouteScope){modal.close();return}replayingDialog=true;try{operationsDayDetail(route.sid,route.day)}finally{replayingDialog=false}};
const operationsPreviousRouteLabel=dialogRouteLabel;
dialogRouteLabel=function(route){return route?.type==='operationsDay'?'day appointments':operationsPreviousRouteLabel(route)};
function updateOperationsBoards(){const subbies=operationsVisibleSubbies(),bookings=filteredPrivateBookings();$('#operationsBoards').innerHTML=subbies.length?(operationsMode==='month'?operationsMonthMarkup(subbies):operationGroups().map(days=>operationsBoard(days,subbies,bookings)).join('')):'<p>No subcontractors match. Add a subbie or clear the filters.</p>'}
renderPrivatePlanner=function(){if(role!=='sevlink'){plannerAllowed();return}if(plannerTab!=='calendar')return previousPrivatePlanner();app.innerHTML=heading('Operations Calendar.','Private team scheduling · SAST · 09:00–17:00',`<div class="toolbar"><button class="secondary" onclick="subbieForm()">＋ Add subbie</button><button class="primary" onclick="bookingForm()">＋ Book appointment</button></div>`)+`<div class="banner"><b>SEVLINK OPERATIONS ONLY</b><br>Clients see Sevlink attending. Subcontractor identities, costs, notes and overlap authorisations stay in this workspace.</div><div class="tabs"><button class="selected" onclick="plannerTab='calendar';renderPrivatePlanner()">Operations Calendar</button><button onclick="plannerTab='bookings';renderPrivatePlanner()">Assignments & dates</button><button onclick="plannerTab='subbies';renderPrivatePlanner()">Subbie directory</button></div><div class="panel operations-panel"><div class="planner-controls"><div class="toolbar"><button class="secondary" onclick="moveOperations(-1)" aria-label="Previous period">←</button><button class="secondary" onclick="privateCalendarDay=new Date(Date.now()+7200000).toISOString().slice(0,10);renderPrivatePlanner()">Today</button><input type="date" id="operationsDate" value="${privateCalendarDay}" aria-label="Calendar date"><button class="secondary" onclick="moveOperations(1)" aria-label="Next period">→</button></div><div class="toolbar">${[['day','Day'],['working','Working Week'],['week','Full Week'],['month','Full Month']].map(([mode,label])=>`<button class="${operationsMode===mode?'primary':'secondary'}" onclick="operationsMode='${mode}';renderPrivatePlanner()">${label}</button>`).join('')}</div></div><div class="planner-controls operations-filters"><input type="search" id="operationsSearch" placeholder="Search subcontractors…" aria-label="Search subcontractors" value="${esc(operationsSearch)}"><select id="operationsSubbie" aria-label="Filter subcontractor"><option value="all">All subcontractors</option>${state.subbies.map(s=>`<option value="${s.id}" ${privateSubbieFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="operationsStatus" aria-label="Filter appointment status">${['All bookings','Awaiting response','Accepted','On Site','Attended','Completed','Declined','Cancelled'].map(s=>`<option ${plannerFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><h2 style="margin:18px 0">${operationsPeriodLabel()}</h2><p class="muted">${operationsMode==='month'?'The full month at a glance. Scroll down through subcontractors; select a count to open the day’s appointments.':'Scroll down for more subcontractors. Open a job block for full details and status updates.'}</p><div id="operationsBoards"></div><p class="muted">${operationsMode==='month'?'Switch to Day or Week for proportional 09:00–17:00 time blocks.':'Block widths reflect appointment duration. Overlapping teams use separate lanes.'}</p></div>`;updateOperationsBoards();$('#operationsDate').onchange=e=>{if(e.target.value){privateCalendarDay=e.target.value;renderPrivatePlanner()}};$('#operationsSearch').oninput=e=>{operationsSearch=e.target.value;updateOperationsBoards()};$('#operationsSubbie').onchange=e=>{privateSubbieFilter=e.target.value;updateOperationsBoards()};$('#operationsStatus').onchange=e=>{plannerFilter=e.target.value;updateOperationsBoards()}};
filteredPrivateBookings=function(){if(role!=='sevlink')return [];return state.privateBookings.filter(b=>(privateSubbieFilter==='all'||b.subbie===privateSubbieFilter)&&(plannerFilter==='All bookings'||operationStatus(b)===plannerFilter))};
function moveOperations(delta){const d=keyDate(privateCalendarDay);if(operationsMode==='month'){d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+delta)}else d.setUTCDate(d.getUTCDate()+delta*(['week','working'].includes(operationsMode)?7:1));privateCalendarDay=dateKey(d);renderPrivatePlanner()}
const renderBeforeOperations=render;
render=function(){renderBeforeOperations();const nav=$('#nav [data-view="privateplanner"]');if(nav)nav.innerHTML='▣ &nbsp; Operations Calendar';if(view==='overview')app.querySelectorAll('button').forEach(b=>{if(/report a repair/i.test(b.textContent))b.remove()})};

// Check both private assignments and existing shared appointments, using half-open intervals.
function operationsConflicts(bid,record){if(role!=='sevlink')return [];const start=Date.parse(record.when+'+02:00'),end=start+record.duration*60000;if(!Number.isFinite(start)||!Number.isFinite(end))return [];const conflicts=state.privateBookings.filter(b=>b.id!==bid&&b.job!==record.job&&b.subbie===record.subbie&&!['Declined','Cancelled','Attended'].includes(b.status)&&start<Date.parse(b.when+'+02:00')+b.duration*60000&&end>Date.parse(b.when+'+02:00')).map(b=>({id:b.id,job:b.job,when:b.when,duration:b.duration}));const j=getJob(record.job);for(const other of state.jobs){if(other.id===record.job||['Completed','Cancelled'].includes(other.status)||other.schedule?.status!=='Confirmed')continue;const b=activeJobBooking(other.id);if(b||other.team!==j?.team)continue;const t=Date.parse(other.schedule.when+'+02:00');if(start<t+(other.duration||60)*60000&&end>t)conflicts.push({id:other.id,job:other.id,when:other.schedule.when,duration:other.duration||60})}return conflicts}
const bookingFormBeforeOperations=bookingForm;
bookingForm=function(bid='',jobid=''){if(role!=='sevlink')return;bookingFormBeforeOperations(bid,jobid);const form=modal.querySelector('#form');if(!form?.elements.when||!form.elements.subbie)return;const warning=document.createElement('div');warning.className='notice operations-conflict';warning.setAttribute('role','alert');warning.hidden=true;form.querySelector('.actions')?.before(warning);if(!warning.parentNode)form.append(warning);const staff=state.sevlinkStaff||[];warning.innerHTML=`<b>⚠ Overlapping appointments</b><div id="operationsConflictList"></div><p>Choose another time or authorise separate teams for this subcontractor.</p><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="allowOverlap" style="width:auto">Sevlink Super Admin authorises overlapping teams</label><label>Authorising Sevlink staff member</label><select name="overlapStaff"><option value="">Select your name</option>${staff.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><label>Reason / teams attending</label><textarea name="overlapReason" maxlength="1500" rows="3" placeholder="Explain which teams cover these simultaneous visits."></textarea>`;const read=()=>({job:form.elements.job.value,subbie:form.elements.subbie.value,when:form.elements.when.value,duration:Number(form.elements.hours.value)*60});const update=()=>{const conflicts=operationsConflicts(bid,read());warning.hidden=!conflicts.length;warning.querySelector('#operationsConflictList').innerHTML=conflicts.map(c=>{const j=getJob(c.job);return `<p><b>${esc(j?.ref)} · ${operationTimeRange(c)}</b><br>${esc(property(j?.property)?.name)} · ${esc(j?.title)}</p>`}).join('');const required=conflicts.length>0&&form.elements.allowOverlap.checked;form.elements.overlapStaff.required=required;form.elements.overlapReason.required=required};['job','subbie','when','hours','allowOverlap'].forEach(name=>form.elements[name].addEventListener('change',update));const submit=form.onsubmit;form.onsubmit=async e=>{update();const conflicts=operationsConflicts(bid,read());if(conflicts.length&&(!form.elements.allowOverlap.checked||!form.elements.overlapStaff.value||!form.elements.overlapReason.value.trim())){e.preventDefault();toast('Resolve the conflict, or select your name and record the overlap reason.');warning.scrollIntoView({block:'center',behavior:'smooth'});return}return submit(e)};update()};
const saveBookingBeforeOperations=savePrivateBooking;
savePrivateBooking=async function(bid,record){if(role!=='sevlink')return false;const form=modal.querySelector('#form');const conflicts=operationsConflicts(bid,record);if(conflicts.length&&form?.elements.allowOverlap?.checked){record.overlapAuthorisation={staffId:form.elements.overlapStaff.value,reason:form.elements.overlapReason.value.trim()}}if(conflicts.length&&(!record.overlapAuthorisation?.reason?.trim()||!state.sevlinkStaff?.some(s=>s.id===record.overlapAuthorisation.staffId))){toast('An overlap needs named Sevlink authorisation and a reason.');return false}return saveBookingBeforeOperations(bid,record)};
const bookingDetailBeforeOperations=privateBookingDetail;
privateBookingDetail=function(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid),j=b&&getJob(b.job);if(!b||!j)return;bookingDetailBeforeOperations(bid);const current=j.schedule?.when===b.when&&['Scheduled','In progress'].includes(j.status);modal.insertAdjacentHTML('beforeend',`<div class="notice"><b>Appointment: ${esc(operationStatus(b))}</b><p>${esc(j.ref)} · ${esc(j.title)}<br>${esc(property(j.property)?.address)}<br>${b.when.slice(0,10)} · ${operationTimeRange(b)} SAST</p>${current?`<div class="actions">${j.status==='Scheduled'?`<button class="secondary" onclick="markJobOnSite('${j.id}').then(ok=>{if(ok)privateBookingDetail('${bid}')})">On Site</button>`:''}<button class="primary" onclick="operationsVisitForm('${j.id}','attended')">Attended</button>${!isAssessmentVisit(j)?`<button class="primary" onclick="operationsVisitForm('${j.id}','completed')">Completed</button>`:''}</div><p>Record the visit summary to update the job and client calendar.</p>`:''}<button class="secondary" onclick="jobDetail('${j.id}','schedule')">Open full job</button></div>${(b.overlapAuthorisations||[]).map(a=>`<div class="notice"><b>Private overlap authorisation · ${esc(a.by)}</b><p>${esc(a.reason)}<br>${date(a.at)} · ${esc(a.when)}</p></div>`).join('')}`)};

function operationsVisitForm(jid,action){if(role!=='sevlink')return;finishVisitForm(jid);const outcome=modal.querySelector('select[name="outcome"]');if(outcome&&!isAssessmentVisit(getJob(jid)))outcome.value=action==='completed'?'completed':'followup'}

if(typeof window!=='undefined'){let operationsNarrow=window.innerWidth<760;window.addEventListener('resize',()=>{const narrow=window.innerWidth<760;if(narrow!==operationsNarrow){operationsNarrow=narrow;if(role==='sevlink'&&view==='privateplanner'&&plannerTab==='calendar')updateOperationsBoards()}})}
